"""Small offline gallery and comparative metrics; never synthesizes game imagery."""
import json, pathlib, statistics, html, gzip
from PIL import Image, ImageDraw

root=pathlib.Path('docs/mission-12-evidence')
before=json.loads((root/'before.json').read_text());after=json.loads((root/'after.json').read_text())
perf=json.loads(gzip.decompress((root/'performance.json.gz').read_bytes()))
manifest=json.loads(pathlib.Path('public/materials/earth/surface-art.json').read_text())
titles={'mineral':'Une rue minérale','nature':'Une prairie documentée','roche':'La pente et la roche','berge':'Au bord de l’Anglin','eau':'La surface de l’eau','riviere':'La rivière dans le paysage','matin':'La lumière du matin','pluie-soir':'La pluie du soir'}
summary=[]
for profile in ['eco','balanced','quality']:
    for station in ['mineral','nature','roche','eau']:
        records={phase:[r for r in perf['rows'] if r['phase']==phase and r['profile']==profile and r['station']==station] for phase in ['before','after']}
        values={phase:[v['ms'] for r in records[phase] for v in r['samples']] for phase in records}
        med={k:statistics.median(v) for k,v in values.items()}
        old,new=[records[k][-1] for k in ['before','after']]
        assert old['samples'][0]['calls']==new['samples'][0]['calls']
        assert old['samples'][0]['triangles']==new['samples'][0]['triangles']
        summary.append({'profile':profile,'station':station,'beforeMs':med['before'],'afterMs':med['after'],'changePercent':(med['after']/med['before']-1)*100,'samplesPerVersion':len(values['before']),'calls':new['samples'][0]['calls'],'triangles':new['samples'][0]['triangles'],'beforeTextures':old['state']['textures'],'afterTextures':new['state']['textures']})
for a,b in zip(before['results'],after['results']):
    assert a['station']==b['station'] and a['state']['matrix']==b['state']['matrix']
    assert a['state']['climate']['date']==b['state']['climate']['date']
    assert a['state']['climate']['weather']==b['state']['climate']['weather']
    assert a['state']['life']['profile']==b['state']['life']['profile']=='balanced'
metrics={'baseline':'83d9258587177593bc3debd681544d7704a68882','environment':perf['environment'],'rows':summary,'textureFilesBytes':sum(manifest['bytes'].values()),'extraTextures':2,'estimatedExtraTextureBytesWithMipmaps':(1024**2+576**2)*4*4/3,'identicalCaptureConditions':True,'limitation':'SwiftShader synchronous software rendering/readback, not physical GPU FPS. Browser JS heap and GPU byte allocation are not inferred from texture counts.'}
(root/'summary.json').write_text(json.dumps(metrics,ensure_ascii=False,indent=2)+'\n')

cards=[]
for row in before['results']:
    name=row['id'];title=titles[name]
    if name in ['mineral','nature','roche','berge','eau','riviere']:
        board=Image.new('RGB',(1920,680),'#101c19');draw=ImageDraw.Draw(board)
        for i,label in enumerate(['Mission 11 · avant','Mission 12A · après']):
            draw.text((20+i*960,12),label,fill='#e7e2cc');board.paste(Image.open(root/f'{["before","after"][i]}-{name}.jpg'),(i*960,40))
        board.save(root/f'compare-{name}.jpg',quality=88,optimize=True)
    category='conditions' if name in ['matin','pluie-soir'] else 'eau' if name in ['berge','eau','riviere'] else 'sols'
    date=html.escape(row['state']['climate']['date']);station=html.escape(str(row['station'][1:]))
    cards.append(f'''<article class="card" data-family="{category}"><h2>{title}</h2><p class="condition">Équilibré · 960 × 640 · {date}</p><div class="pair"><figure><a href="before-{name}.jpg" target="_blank"><img src="before-{name}.jpg" loading="lazy" alt="{title} — Mission 11"></a><figcaption>Mission 11 · avant</figcaption></figure><figure><a href="after-{name}.jpg" target="_blank"><img src="after-{name}.jpg" loading="lazy" alt="{title} — Mission 12A"></a><figcaption>Mission 12A · après</figcaption></figure></div><details><summary>Caméra et position de référence</summary><code>{station}</code><p>Coordonnées locales métriques, même matrice et même altitude source. Les stations de photographie ne prouvent pas un accès piéton réel.</p></details></article>''')

rows=''.join(f"<tr><th>{ {'eco':'Éco','balanced':'Équilibré','quality':'Qualité'}[r['profile']]}</th><td>{titles[r['station']]}</td><td>{r['beforeMs']:.1f}</td><td>{r['afterMs']:.1f}</td><td>+{r['changePercent']:.1f} %</td><td>{r['calls']} / {r['triangles']:,}</td></tr>" for r in summary)
page='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Endless Earth — Mission 12A</title><style>
:root{color-scheme:dark;font:16px/1.6 system-ui,sans-serif;background:#101b18;color:#e5e7dc}*{box-sizing:border-box}body{margin:0}main,header{max-width:1300px;margin:auto;padding:32px 24px}header{padding-top:64px}h1{font:clamp(2.3rem,6vw,4rem)/1.07 Georgia,serif;max-width:800px;margin:12px 0 24px}h2{font:1.8rem/1.2 Georgia,serif;margin:0 0 12px}h3{font-size:1.1rem}p{max-width:900px;color:#bdc9bf}.eyebrow{letter-spacing:.18em;font-size:.76rem;color:#bfc595;text-transform:uppercase}.tag{display:inline-block;border:1px solid #7e8966;border-radius:30px;padding:5px 12px;font-size:.8rem}a{color:#d1d9ae}nav{display:flex;gap:9px;flex-wrap:wrap;margin:28px 0}button{font:inherit;border:1px solid #4d6659;background:#1b3027;color:#e4e6d4;padding:8px 17px;border-radius:24px;cursor:pointer}button[aria-pressed=true]{background:#d1d5b6;color:#17251d}.card{border-top:1px solid #34463b;padding:28px 0 38px}.condition{font-size:.8rem;margin-top:0}.pair{display:grid;grid-template-columns:1fr 1fr;gap:12px}figure{margin:0}img{display:block;width:100%;height:auto;border-radius:8px}figcaption{padding:7px 2px;font-size:.8rem;color:#c2c9b6}details{font-size:.85rem;color:#aebbad;margin-top:16px}code{overflow-wrap:anywhere}summary{cursor:pointer}section{margin:34px 0 60px}video{width:100%;border-radius:9px;background:#080d0a}.video-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.table{overflow:auto}table{width:100%;border-collapse:collapse;font-size:.83rem;white-space:nowrap}td,th{border-bottom:1px solid #34463b;padding:9px;text-align:left}thead{color:#cfd3ab}.note{border-left:3px solid #bfc595;padding-left:18px}.links{display:flex;gap:20px;flex-wrap:wrap}footer{padding:32px 0 70px;border-top:1px solid #34463b;font-size:.85rem;color:#a7b6a7}[hidden]{display:none!important}@media(max-width:760px){main,header{padding-left:16px;padding-right:16px}.pair,.video-grid{grid-template-columns:1fr}h1{font-size:2.6rem}header{padding-top:38px}}
</style><header><div class="eyebrow">Endless Earth · Mission 12 · Jalon A</div><h1>La terre, l’eau,<br>la poésie des lieux.</h1><p>Huit vues du vrai jeu, à conditions identiques. Des matières plus lisibles, une rivière liée au ciel, des berges liées à leur géographie.</p><span class="tag">À évaluer par le propriétaire · B, C et D non commencés</span><p class="links"><a href="../mission-12.md">Rapport complet</a><a href="/endless-earth/?moment=afternoon&weather=clear">Ouvrir le jeu local</a><a href="summary.json">Mesures et protocole</a></p></header><main>
<section aria-labelledby="captures"><h2 id="captures">Les lieux, avant et après</h2><p>À gauche : Mission 11 fusionnée, commit <code>83d9258</code>. À droite : ce Jalon A. Images originales du moteur ; mêmes caméras, heure, météo, profil et résolution. Cliquer une image pour l’ouvrir en entier.</p><nav aria-label="Filtrer les vues"><button data-filter="all" aria-pressed="true">Tout voir</button><button data-filter="sols" aria-pressed="false">Terre et roche</button><button data-filter="eau" aria-pressed="false">Eau et berges</button><button data-filter="conditions" aria-pressed="false">Matin et pluie</button></nav>''' + ''.join(cards)+'''</section>
<section><h2>Une vraie promenade</h2><p>Captures natives du canvas WebGL et du son réel du jeu, sans accélération ni normalisation du son. Le personnage suit les voies OSM avec le contrôleur et les collisions habituels. Ces clips courts ne remplacent pas un test de longue marche.</p><div class="video-grid"><figure><video controls preload="metadata" src="before-promenade.webm"></video><figcaption>Avant · promenade automatique, 32 secondes</figcaption></figure><figure><video controls preload="metadata" src="after-promenade.webm"></video><figcaption>Après · promenade automatique, 32 secondes</figcaption></figure></div><h3>Pause près de la rivière</h3><video controls preload="metadata" src="after-eau.webm"></video><p>Station d’inspection distincte sur la berge. Passage du matin clair au soir pluvieux par les commandes ordinaires du jeu. Ce plan séparé n’est pas présenté comme la continuation du parcours précédent.</p></section>
<section><h2>Le coût du rendu</h2><p>Chromium / SwiftShader · 800 × 600 · trois passages · douze échantillons par version et station. Ordre avant/après alterné. Temps médian de rendu synchronisé avec lecture RGBA, en millisecondes ; <strong>ce ne sont pas des FPS sur GPU physique</strong>.</p><div class="table"><table><thead><tr><th>Profil</th><th>Station</th><th>Avant ms</th><th>Après ms</th><th>Écart</th><th>Appels / triangles identiques</th></tr></thead><tbody>'''+rows+'''</tbody></table></div><p>Deux textures partagées supplémentaires, environ 0,75 Mo de fichiers et 7,02 Mio de stockage RGBA avec mipmaps estimé. Aucune multiplication des objets. Le surcoût logiciel reste explicite ; la validation sur GPU physique et Android est encore nécessaire.</p></section>
<section><h2>Choisir une matière</h2><p>Comparaison de la roche CC0 sélectionnée et d’une alternative procédurale, dans le moteur, avec la même teinte régionale et la même caméra. La photo n’est pas une observation d’Angles ; elle fournit une matière générique et reste distincte de la géographie.</p><div class="pair"><figure><img src="asset-photo.jpg" alt="Roche CC0 dans le moteur"><figcaption>Rock Face 03 · retenue, CC0</figcaption></figure><figure><img src="asset-procedural.jpg" alt="Alternative de roche procédurale"><figcaption>Alternative procédurale · étude</figcaption></figure></div><p class="links"><a href="/endless-earth/materials/earth/catalog.json">Catalogue et provenance</a><a href="/endless-earth/materials/earth/LICENSE-CC0.txt">Licence CC0</a><a href="resources.json">Autres bibliothèques étudiées</a></p></section>
<section class="note"><h2>Ce qui reste à apprécier</h2><p>La richesse à distance de marche, le grain des sols, la répétition, l’harmonie roche/végétation et le mouvement de l’eau demandent votre évaluation. Les limites du relief à 10 m, les bâtiments sur pentes et les ruines illustratives restent visibles ; aucun changement caché de géométrie ne les masque.</p><p>Jalon A uniquement. La PR reste en brouillon. Aucune fusion ni publication de production ; votre accord explicite est attendu avant le Jalon B.</p></section><footer>IGN / ASP · Licence Ouverte 2.0 · © OpenStreetMap contributors · ODbL. Rock Face 03 : Dario Barresi / Rico Cilliers, Poly Haven, CC0. Les autres matières nouvelles sont procédurales et originales. Captures réelles ; aucune illustration générée.</footer></main><script>
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{const filter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelectorAll('[data-family]').forEach(card=>card.hidden=filter!=='all'&&card.dataset.family!==filter)}));
</script></html>'''
(root/'index.html').write_text(page)
print(json.dumps(metrics,ensure_ascii=False))
